using System;using System.Drawing;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;namespace ServiceTool{static class Quick40{static IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var d in Walk(c))yield return d;}}[STAThread]static int Main(){Application.EnableVisualStyles();try{int checks=0;foreach(bool dark in new[]{false,true})foreach(Form form in new Form[]{new MainForm(null,true),new LibraryManagerForm(true),new ManagerHub(),new DotNetUpdatesForm(()=>null)})using(form){var m=form as ManagerModuleForm;if(m!=null)m.SetTheme(dark,false);var service=form as MainForm;if(service!=null)service.SetTheme(dark,false);form.Show();Application.DoEvents();if(form is MainForm){var toggle=Walk(form).OfType<RefreshToggle>().Single();var table=Walk(form).OfType<ServiceGrid>().Single();var action=Walk(form).OfType<Button>().Single(b=>b.Text=="Открыть службы");int top=toggle.PointToScreen(Point.Empty).Y-action.PointToScreen(new Point(0,action.Height)).Y;int bottom=table.PointToScreen(Point.Empty).Y-toggle.PointToScreen(new Point(0,toggle.Height)).Y;if(Math.Abs(top-bottom)>2)throw new Exception("Unequal toggle gaps: "+top+" / "+bottom);if(Math.Abs(toggle.PointToScreen(new Point(toggle.Width,0)).X-table.PointToScreen(new Point(table.Width,0)).X)>1)throw new Exception("Toggle right edge mismatch");checks+=2;}foreach(var button in Walk(form).OfType<BrandButton>()){if(button.Visible&&!button.Parent.ClientRectangle.Contains(button.Bounds))throw new Exception("Outside parent: "+form.GetType().Name+" "+button.Text);checks++;}if(form is DotNetUpdatesForm&&Walk(form).OfType<ServiceGrid>().Single().Rows.Count==0)throw new Exception("Empty initial .NET list");}Console.WriteLine("PASS: "+checks+" short button-bound checks and initial inventory; no network or installers.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}}}